-- =====================================================================
--  Base "College" — version normalisée pour SQLite (>= 3.15)
--  Source : export SQLite DB_College.db.sql
--  Exécution :  sqlite3 college.db < DB_College_sqlite.sql
--  (ou « Exécuter le SQL » dans DB Browser for SQLite)
--
--  IMPORTANT : SQLite ne vérifie les clés étrangères que si on l'active,
--  à CHAQUE connexion :  PRAGMA foreign_keys = ON;
-- =====================================================================

PRAGMA foreign_keys = ON;

BEGIN;

-- ---------------------------------------------------------------------
-- 0. Nettoyage (permet de relancer le script)
-- ---------------------------------------------------------------------
DROP VIEW  IF EXISTS v_moyennes;
DROP TABLE IF EXISTS notes           ;
DROP TABLE IF EXISTS evaluations     ;
DROP TABLE IF EXISTS inscriptions    ;
DROP TABLE IF EXISTS seances_maitres ;
DROP TABLE IF EXISTS seances         ;
DROP TABLE IF EXISTS eleves          ;
DROP TABLE IF EXISTS groupes         ;
DROP TABLE IF EXISTS cours           ;
DROP TABLE IF EXISTS salles          ;
DROP TABLE IF EXISTS maitres         ;

-- ---------------------------------------------------------------------
-- 1. Entités
-- ---------------------------------------------------------------------
-- Remarque : SQLite n'a pas de type énuméré. Le jour est un TEXT contrôlé
-- par CHECK ; pour trier dans l'ordre de la semaine, utiliser par ex.
--   ORDER BY instr('LuMaMeJeVe', substr(jour, 1, 2))

CREATE TABLE maitres (
    no_maitre          INTEGER      PRIMARY KEY,
    nom                VARCHAR(50)  NOT NULL,
    prenom             VARCHAR(50)  NOT NULL,
    sexe               CHAR(1)      NOT NULL CHECK (sexe IN ('F', 'M')),
    date_naissance     TEXT         NOT NULL CHECK (date(date_naissance) IS date_naissance)
);

-- Groupe : le premier chiffre du numéro EST le degré (101 -> degré 1).
-- La contrainte CHECK garantit cette règle.
CREATE TABLE groupes (
    no_groupe          INTEGER      PRIMARY KEY,
    numero             VARCHAR(10)  NOT NULL UNIQUE,
    degre_pedagogique  SMALLINT     NOT NULL CHECK (degre_pedagogique BETWEEN 1 AND 4),
    no_maitre          INTEGER      NOT NULL REFERENCES maitres (no_maitre),  -- maître de groupe
    CHECK (substr(numero, 1, 1) = CAST(degre_pedagogique AS TEXT))
);

-- Le degré n'est plus stocké dans eleves : il se déduit du groupe
-- (sinon dépendance transitive no_eleve -> no_groupe -> degre, contraire à la 3FN).
CREATE TABLE eleves (
    no_eleve           INTEGER      PRIMARY KEY,
    nom                VARCHAR(50)  NOT NULL,
    prenom             VARCHAR(50)  NOT NULL,
    sexe               CHAR(1)      NOT NULL CHECK (sexe IN ('F', 'M')),
    date_naissance     TEXT         NOT NULL CHECK (date(date_naissance) IS date_naissance),
    nationalite        VARCHAR(50)  NOT NULL,
    no_groupe          INTEGER      NOT NULL REFERENCES groupes (no_groupe)
);


CREATE TABLE salles (
    no_salle           INTEGER      PRIMARY KEY,
    salle              VARCHAR(10)  NOT NULL UNIQUE,
    max_eleves         SMALLINT     NOT NULL CHECK (max_eleves >= 0),
    lignes             SMALLINT     NOT NULL CHECK (lignes   >= 0),
    colonnes           SMALLINT     NOT NULL CHECK (colonnes >= 0),
    type_salle         VARCHAR(50)  NOT NULL
);

CREATE TABLE cours (
    no_cours           INTEGER      PRIMARY KEY,
    libelle_cours      VARCHAR(20)  NOT NULL UNIQUE,
    max_eleves         SMALLINT     NOT NULL CHECK (max_eleves > 0),
    no_maitre          INTEGER      NOT NULL REFERENCES maitres (no_maitre),
    UNIQUE (no_cours, no_maitre)     -- cible de la FK composée de seances
);

-- ---------------------------------------------------------------------
-- 2. Associations
-- ---------------------------------------------------------------------

-- Une séance = une plage horaire d'un cours dans une salle, pour un semestre.
-- Un cours annuel a une ligne par semestre ; deux cours en alternance
-- (ex. droit au S1 / économie au S2) partagent la même plage horaire.
--
-- no_maitre est une COPIE contrôlée de cours.no_maitre : la FK composée
-- (no_cours, no_maitre) -> cours garantit qu'elle est toujours identique
-- (ON UPDATE CASCADE la met à jour si on change le maître du cours).
-- Cette copie permet d'interdire, par une simple contrainte UNIQUE,
-- qu'un maître ait deux séances au même moment.
CREATE TABLE seances (
    no_salle           INTEGER       NOT NULL REFERENCES salles (no_salle),
    jour               TEXT          NOT NULL CHECK (jour IN ('Lundi', 'Mardi', 'Mercredi', 'Jeudi', 'Vendredi')),
    periode            INTEGER       NOT NULL CHECK (periode BETWEEN 1 AND 12),
    semestre           INTEGER       NOT NULL CHECK (semestre IN (1, 2)),
    no_cours           INTEGER       NOT NULL,
    no_maitre          INTEGER       NOT NULL,
    PRIMARY KEY (no_salle, jour, periode, semestre),   -- une salle : un cours à la fois
    UNIQUE (no_cours,  jour, periode, semestre),       -- un cours  : une salle à la fois
    UNIQUE (no_maitre, jour, periode, semestre),       -- un maître : une séance à la fois
    FOREIGN KEY (no_cours, no_maitre)
        REFERENCES cours (no_cours, no_maitre) ON UPDATE CASCADE ON DELETE CASCADE
);

-- Inscription d'un élève à un cours.
-- moyenne_bulletin = note OFFICIELLE saisie par le maître en fin d'année.
-- Elle s'appuie sur les notes de l'année mais n'est pas calculée (arrondi,
-- appréciation du maître, décision de conférence...) : ce n'est donc pas une
-- redondance. NULL tant qu'elle n'est pas attribuée.
-- La moyenne CALCULÉE à partir des notes est donnée par la vue v_moyennes.
CREATE TABLE inscriptions (
    no_eleve           INTEGER       NOT NULL REFERENCES eleves (no_eleve) ON DELETE CASCADE,
    no_cours           INTEGER       NOT NULL REFERENCES cours  (no_cours) ON DELETE CASCADE,
    date_inscription   TEXT          NOT NULL DEFAULT CURRENT_DATE CHECK (date(date_inscription) IS date_inscription),
    moyenne_bulletin   REAL          CHECK (moyenne_bulletin BETWEEN 1 AND 6),
    PRIMARY KEY (no_eleve, no_cours)
);

-- Notes d'un élève dans un cours : autant de notes que nécessaire.
-- Échelle suisse 1 à 6. La FK composée garantit que l'élève est INSCRIT au cours.
CREATE TABLE notes (
    no_note            INTEGER       PRIMARY KEY,     -- numéroté automatiquement (alias du rowid)
    no_eleve           INTEGER       NOT NULL,
    no_cours           INTEGER       NOT NULL,
    note               REAL          NOT NULL CHECK (note BETWEEN 1 AND 6),
    date_note          TEXT          NOT NULL DEFAULT CURRENT_DATE CHECK (date(date_note) IS date_note),
    FOREIGN KEY (no_eleve, no_cours)
        REFERENCES inscriptions (no_eleve, no_cours) ON DELETE CASCADE
);

-- ---------------------------------------------------------------------
-- 3. Données
-- ---------------------------------------------------------------------


-- maitres (112 lignes)

-- groupes (36 lignes)
--   Reprises des cours "Groupe101" ... "Groupe408" de la base d'origine :
--   une heure par semaine avec le groupe, donnée par un maître qui enseigne aussi
--   une autre branche au groupe -> ce maître devient le maître de groupe.
--   Ces 36 cours sont supprimés (avec leur séance, leurs inscriptions et
--   leurs 838 notes d'origine).

-- eleves (840 lignes)
--   Groupe = celui du cours "GroupeXXX" que suit l'élève (838 élèves, un seul
--   groupe chacun, toujours du bon degré). Les 2 élèves sans aucun cours
--   (3247648 -> 301, 5218883 -> 201) sont placés dans le plus petit groupe de leur degré.


-- salles (82 lignes)

-- cours (589 lignes)
--   Maître du cours : dans la base d'origine, 10 cours en co-enseignement
--   (1FRdf-05, 3FRdf-04, 2BIdf-05/06/07, 3BIos-03/04, 3EPdp-01/02, EPI-01/02)
--   avaient 2 à 5 maîtres. Règle appliquée : on garde le plus petit numéro.


-- seances (2798 lignes)
--   Semestre : dans la base d'origine, certaines paires de cours occupaient la
--   même plage horaire avec les mêmes élèves, le même maître ou la même salle
--   (options OC-01 / oC-02, droit / économie, DI / français, demi-groupes...).
--   On les interprète comme une ALTERNANCE : la séance du cours au plus petit
--   libellé est placée au semestre 1, celle de l'autre au semestre 2
--   (152 séances concernées). Toutes les autres séances sont annuelles
--   (une ligne pour le S1 et une pour le S2). Paires concernées :
--     1DIdf-01      / 1FRdf-01        1DIdf-02      / 1FRdf-02     
--     1DIdf-03      / 1FRdf-03        1DIdf-04      / 1FRdf-04     
--     1DIdf-05      / 1FRdf-05        1DIdf-06      / 1FRdf-06     
--     1DIdf-07      / 1FRdf-07        1DIdf-08      / 1FRdf-08     
--     1DIdf-09      / 1FRdf-09        1DIdf-10      / 1FRdf-10     
--     1DIdf-11      / 1FRdf-11        1DIdf-12      / 1FRdf-12     
--     1DRdf-01      / 1DRdf-02        1DRdf-01      / 1ECdf-01     
--     1DRdf-02      / 1ECdf-02        1DRdf-03      / 1ECdf-03     
--     1DRdf-04      / 1ECdf-04        1DRdf-06      / 1ECdf-06     
--     1DRdf-07      / 1ECdf-07        1DRdf-08      / 1ECdf-08     
--     1ECdf-01      / 1ECdf-02        1ECdf-05      / 1HAdf-02     
--     1HAdf-01      / 1HAdf-02        1HAdf-03      / 1HAdf-04     
--     1HAdf-08      / 1HAdf-09        2ANdf-04      / EPI-02       
--     2HAdf-01      / 2HAdf-02        2HAdf-03      / 2HAdf-04     
--     2HAdf-05      / 2HAdf-06        3APOs-01b     / 3APoS-01c    
--     3APOs-01b     / 3APoS-02c       3APOs-02b     / 3APoS-01c    
--     3APOs-02b     / 3APoS-02c       3GEOc-01      / 3GEoC-02     
--     3HI/LAOc-01   / 3HI/LAoC-02b    3HI/THOC-01   / 3HI/THOC-02  
--     3HIOc-01      / 3HIoC-02        3POOc-01      / 3POoC-02     
--     3PYOc-01      / 3PYoC-02        3SPOc-01      / 3SPoC-02     
--     4EDOc-01      / 4EDoC-02        4GEOc-01      / 4GEoC-02     
--     4HI/LAOc-01   / 4HI/LAoC-02b    4HIOc-01      / 4HIoC-02     
--     4POOc-01      / 4POoC-02        4PYOc-01      / 4PYoC-02     
--     4SPOc-01a     / 4SPoC-01b       4SPOc-02a     / 4SPoC-02b    






-- inscriptions (11042 lignes)
--   moyenne_bulletin : la note unique de la base SQLite d'origine (données réelles) ;
--   date_inscription : GÉNÉRÉE, entre le 1er mai et le 25 août 2023, avant la rentrée.























-- notes (32767 lignes)
--   Notes de l'année, toutes GÉNÉRÉES pour l'exercice (la note d'origine est
--   devenue inscriptions.moyenne_bulletin) : 1 à 5 épreuves par cours,
--     même date pour tous les élèves du cours (un jour de 2023-2024 où le cours a lieu,
--     dans le semestre où il a lieu ; S2 à partir du 29 janvier 2024),
--     valeur = moyenne de bulletin de l'élève + difficulté de l'épreuve + variation
--     aléatoire, arrondie au demi-point ; ~2 % d'absents (pas de note).


































































-- ---------------------------------------------------------------------
-- 4. Index sur les clés étrangères
--    (SQLite n'indexe PAS automatiquement les colonnes FK)
-- ---------------------------------------------------------------------
CREATE INDEX idx_seances_creneau         ON seances         (jour, periode);
CREATE INDEX idx_cours_maitre            ON cours           (no_maitre);
CREATE INDEX idx_groupes_maitre          ON groupes         (no_maitre);
CREATE INDEX idx_eleves_groupe           ON eleves          (no_groupe);
CREATE INDEX idx_inscriptions_cours      ON inscriptions    (no_cours);
CREATE INDEX idx_notes_inscription       ON notes           (no_eleve, no_cours);

-- ---------------------------------------------------------------------
-- 5. Moyenne CALCULÉE de chaque élève dans chaque cours, à côté de la
--    moyenne de bulletin saisie
--    (NULL tant que l'élève n'a aucune note ; arrondie au demi-point)
-- ---------------------------------------------------------------------
CREATE VIEW v_moyennes AS
SELECT i.no_eleve, i.no_cours,
       i.moyenne_bulletin,
       COUNT(n.note)                                   AS nb_notes,
       ROUND(AVG(n.note), 2)                           AS moyenne,
       ROUND(AVG(n.note) * 2) / 2                      AS moyenne_arrondie
FROM   inscriptions i
LEFT JOIN notes n ON n.no_eleve = i.no_eleve AND n.no_cours = i.no_cours
GROUP BY i.no_eleve, i.no_cours, i.moyenne_bulletin;

COMMIT;

ANALYZE;
